#include "stdlib/ml/base/loss/float32/hinge_gradient.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/constants/float32/nan.h"

/**
* Computes the hinge loss gradient with respect to a model parameter for a single-precision floating-point number.
*
* @param x    input value
* @param t    margin threshold
* @param y    true target value
* @param p    predicted value
* @return     hinge loss gradient
*
* @example
* float out = stdlib_base_float32_hinge_gradient( 2.5f, 1.0f, 1.0f, 0.202f );
* // returns -2.5f
*/
float stdlib_base_float32_hinge_gradient( const float x, const float t, const float y, const float p ) {
	if (
		stdlib_base_is_nanf( x ) || stdlib_base_is_nanf( t ) || stdlib_base_is_nanf( y ) || stdlib_base_is_nanf( p ) ||
		( y != -1.0f && y != 1.0f )
	) {
		return STDLIB_CONSTANT_FLOAT32_NAN;
	}
	if ( y*p <= t ) {
		return -x * y;
	}
	return 0.0f;
}
